  cancel(pnrNumber, travelDate, email) {
    this.loader.showLoadingDefault();
    this.apiFactory.getTicketDetails(pnrNumber).subscribe(result => {
      // debugger;
      this.loader.hideLoadingDefault();
      try {
        if (typeof result.code == "undefined") {
          this.commonStorage.setItem('cancelTicketDetails', result);
          let emailValidation = email !== result.passenger_details[0].email;
          let dateValidation = travelDate !== result.travel_date;
          let cancelStatus = result.ticket_status == 'Cancelled';
          if (!emailValidation && !dateValidation && !cancelStatus) {
            return true;
          } else {
            if (emailValidation && dateValidation) {
              this.util.showAlert('', 'Email and Date you entered is mismatching');
            } else if (dateValidation) {
              this.util.showAlert('', 'Date you entered is mismatching');
            } else if (emailValidation) {
              this.util.showAlert('', 'Email you entered is mismatching');
            } else if (cancelStatus) {
              this.util.showAlert('', 'Your ticket is allready cancelled');
            }
            return false;
          }
        } else {
          this.util.showAlert('', result.message);
          return false;
        }
      } catch (error) {
        this.util.showAlert('', 'Cannot cancel your ticket try Again after sometime');
        this.ex.call("MyBookingsPage", "cancel()", error);
        return false;
      }
    }, error => {
      this.loader.hideLoadingDefault();
      this.util.showAlert('', 'Cannot cancel your ticket try Again after sometime');
      this.ex.call("MyBookingsPage", "cancel()", error);
      return false;
    });
  }
  setRecentSearches(searchObj) {
    let recentSearches = [];
    if (this.commonStorage.localHas('recentSearches')) {
      recentSearches = this.commonStorage.localGet('recentSearches');
    } else {
      recentSearches = [];
    }
    for (let i = 0; i < recentSearches.length; i++) {
      // if(recentSearches[i].originCity && recentSearches[i].originCity.destCity &&  recentSearches[i].originCity.departureDate){
      if (recentSearches[i].originCity.id == searchObj.originCity.id && recentSearches[i].destCity.id == searchObj.destCity.id && recentSearches[i].departureDate.formattedDate == searchObj.departureDate.formattedDate) {
        recentSearches = this.removeRecentSearch(i);
      }
      // }
    }
    if (recentSearches.length >= 10) {
      recentSearches.pop();
      recentSearches.unshift(searchObj);
    } else {
      recentSearches.unshift(searchObj);
    }
    this.commonStorage.localSet('recentSearches', recentSearches);
  }
  getRecentSearches() {
    let recentSearches = [];
    if (this.commonStorage.localHas('recentSearches')) {
      recentSearches = this.commonStorage.localGet('recentSearches');
    } else {
      recentSearches = [];
    }
    return recentSearches;
  }
  removeRecentSearch(index) {
    let recentSearches = this.commonStorage.localGet('recentSearches');
    recentSearches.splice(index, 1);
    this.commonStorage.localSet('recentSearches', recentSearches);
    return this.commonStorage.localGet('recentSearches');
  }
