  gTrack(msg, action = 'click') {
    // console.log("tracking ", msg);
    msg = location.origin + " : " + msg;
    try {
      this.ga.trackView(msg).then(() => {
        console.log('track view called');
      });
      this.ga.trackEvent(location.origin, msg + ":" + action).then(() => {
        console.log('track event called');
      });
    } catch (err) {
      // console.log("track err", err)
    }
  }
